# The system's .pc files, copied verbatim from Ubuntu 24.04's packages.
SYSTEM = {
    'glib-2.0': 'prefix=/usr\nbindir=${prefix}/bin\ndatadir=${prefix}/share\nincludedir=${prefix}/include\nlibdir=${prefix}/lib/x86_64-linux-gnu\n\nglib_genmarshal=${bindir}/glib-genmarshal\ngobject_query=${bindir}/gobject-query\nglib_mkenums=${bindir}/glib-mkenums\nglib_valgrind_suppressions=${datadir}/glib-2.0/valgrind/glib.supp\n\nName: GLib\nDescription: C Utility Library\nVersion: 2.80.0\nRequires.private: libpcre2-8 >= 10.32\nLibs: -L${libdir} -lglib-2.0\nLibs.private: -lm -pthread\nCflags: -I${includedir}/glib-2.0 -I${libdir}/glib-2.0/include\n',
    'gobject-2.0': 'prefix=/usr\nincludedir=${prefix}/include\nlibdir=${prefix}/lib/x86_64-linux-gnu\n\nName: GObject\nDescription: GLib Type, Object, Parameter and Signal Library\nVersion: 2.80.0\nRequires: glib-2.0\nRequires.private: libffi >=  3.0.0\nLibs: -L${libdir} -lgobject-2.0\nCflags: -I${includedir}\n',
    'gio-2.0': 'prefix=/usr\nbindir=${prefix}/bin\ndatadir=${prefix}/share\nincludedir=${prefix}/include\nlibdir=${prefix}/lib/x86_64-linux-gnu\n\nschemasdir=${datadir}/glib-2.0/schemas\ndtdsdir=${datadir}/glib-2.0/dtds\ngiomoduledir=${libdir}/gio/modules\ngio=${bindir}/gio\ngio_querymodules=${libdir}/glib-2.0/gio-querymodules\nglib_compile_schemas=${libdir}/glib-2.0/glib-compile-schemas\nglib_compile_resources=${bindir}/glib-compile-resources\ngdbus=${bindir}/gdbus\ngdbus_codegen=${bindir}/gdbus-codegen\ngresource=${bindir}/gresource\ngsettings=${bindir}/gsettings\n\nName: GIO\nDescription: glib I/O library\nVersion: 2.80.0\nRequires: glib-2.0, gobject-2.0\nRequires.private: gmodule-no-export-2.0, zlib, mount >= 2.23, libselinux >= 2.2\nLibs: -L${libdir} -lgio-2.0\nCflags: -I${includedir}\n',
    'gmodule-no-export-2.0': 'prefix=/usr\nincludedir=${prefix}/include\nlibdir=${prefix}/lib/x86_64-linux-gnu\n\ngmodule_supported=true\n\nName: GModule\nDescription: Dynamic module loader for GLib\nVersion: 2.80.0\nRequires: glib-2.0\nLibs: -L${libdir} -lgmodule-2.0 -pthread\nCflags: -I${includedir} -pthread\n',
    'libffi': 'prefix=/usr\nexec_prefix=${prefix}\nlibdir=${exec_prefix}/lib\nincludedir=${prefix}/include\n\nName: libffi\nDescription: Library supporting Foreign Function Interfaces\nVersion: 3.4.6\nLibs: -lffi\nCflags: -I${includedir}\n',
    'libpcre2-8': '# Package Information for pkg-config\n\nprefix=/usr\nexec_prefix=${prefix}\nlibdir=${prefix}/lib/x86_64-linux-gnu\nincludedir=${prefix}/include\n\nName: libpcre2-8\nDescription: PCRE2 - Perl compatible regular expressions C library (2nd API) with 8 bit character support\nVersion: 10.42\nLibs: -L${libdir} -lpcre2-8\nLibs.private:  \nCflags: -I${includedir} \n',
    'zlib': 'prefix=/usr\nexec_prefix=${prefix}\nlibdir=${prefix}/lib/x86_64-linux-gnu\nsharedlibdir=${libdir}\nincludedir=${prefix}/include\n\nName: zlib\nDescription: zlib compression library\nVersion: 1.3\n\nRequires:\nLibs: -L${libdir} -L${sharedlibdir} -lz\nCflags: -I${includedir}\n',
    'mount': '# SPDX-License-Identifier: LGPL-2.1-or-later\n#\n# This file is part of libmount from util-linux project.\n#\n# Copyright (C) 2008-2018 Karel Zak <kzak@redhat.com>\n#\n# libmount is free software; you can redistribute it and/or modify it\n# under the terms of the GNU Lesser General Public License as published by\n# the Free Software Foundation; either version 2.1 of the License, or\n# (at your option) any later version.\n#\nprefix=/usr\nexec_prefix=/usr\nlibdir=/usr/lib/x86_64-linux-gnu\nincludedir=/usr/include\n\nName: mount\nDescription: mount library\nVersion: 2.39.3\nRequires.private: blkid libselinux \nCflags: -I${includedir}/libmount\nLibs: -L${libdir} -lmount\nLibs.private: -ldl\n',
    'blkid': 'prefix=/usr\nexec_prefix=/usr\nlibdir=/usr/lib/x86_64-linux-gnu\nincludedir=/usr/include\n\nName: blkid\nDescription: Block device id library\nVersion: 2.39.3\nCflags: -I${includedir}/blkid\nLibs: -L${libdir} -lblkid\n',
    'libselinux': 'prefix=/usr\nexec_prefix=${prefix}\nlibdir=/usr/lib\nincludedir=/usr/include\n\nName: libselinux\nDescription: SELinux utility library\nVersion: 3.5\nURL: http://userspace.selinuxproject.org/\nRequires.private: libsepol libpcre2-8\nLibs: -L${libdir} -lselinux\nCflags: -I${includedir}\n',
    'libsepol': 'prefix=/usr\nexec_prefix=${prefix}\nlibdir=/usr/lib/x86_64-linux-gnu\nincludedir=/usr/include\n\nName: libsepol\nDescription: SELinux policy library\nVersion: 3.5\nURL: http://userspace.selinuxproject.org/\nLibs: -L${libdir} -lsepol\nCflags: -I${includedir}\n',
    'libpng16': 'prefix=/usr\nexec_prefix=${prefix}\nlibdir=${prefix}/lib/x86_64-linux-gnu\nincludedir=${prefix}/include/libpng16\n\nName: libpng\nDescription: Loads and saves PNG files\nVersion: 1.6.43\nRequires.private: zlib\nLibs: -L${libdir} -lpng16\nLibs.private: -lm -lz -lm \nCflags: -I${includedir}\n',
    'libpng': 'prefix=/usr\nexec_prefix=${prefix}\nlibdir=${prefix}/lib/x86_64-linux-gnu\nincludedir=${prefix}/include/libpng16\n\nName: libpng\nDescription: Loads and saves PNG files\nVersion: 1.6.43\nRequires.private: zlib\nLibs: -L${libdir} -lpng16\nLibs.private: -lm -lz -lm \nCflags: -I${includedir}\n',
    'freetype2': 'prefix=/usr\nexec_prefix=/usr\nlibdir=/usr/lib/x86_64-linux-gnu\nincludedir=/usr/include\n\nName: FreeType 2\nURL: https://freetype.org\nDescription: A free, high-quality, and portable font engine.\nVersion: 26.1.20\nRequires: \nRequires.private: zlib, libpng, libbrotlidec\nLibs: -L/usr/lib/x86_64-linux-gnu -lfreetype\nLibs.private: -lbz2\nCflags: -I${includedir}/freetype2\n',
    'libbrotlidec': 'prefix=/usr\nexec_prefix=/usr\nlibdir=${prefix}/lib/x86_64-linux-gnu\nincludedir=${prefix}/include\n\nName: libbrotlidec\nURL: https://github.com/google/brotli\nDescription: Brotli decoder library\nVersion: 1.1.0\nLibs: -L${libdir} -lbrotlidec\nRequires.private: libbrotlicommon >= 1.1.0\nCflags: -I${includedir}\n',
    'libbrotlicommon': 'prefix=/usr\nexec_prefix=/usr\nlibdir=${prefix}/lib/x86_64-linux-gnu\nincludedir=${prefix}/include\n\nName: libbrotlicommon\nURL: https://github.com/google/brotli\nDescription: Brotli common dictionary library\nVersion: 1.1.0\nLibs: -L${libdir} -lbrotlicommon\nCflags: -I${includedir}\n',
    'expat': 'prefix=/usr\nexec_prefix=${prefix}\nlibdir=${prefix}/lib/x86_64-linux-gnu\nincludedir=${prefix}/include\n\nName: expat\nVersion: 2.6.1\nDescription: expat XML parser\nURL: https://libexpat.github.io/\nLibs: -L${libdir} -lexpat\nLibs.private: -lm\nCflags: -I${includedir}\nCflags.private: -DXML_STATIC\n',
    'fontconfig': 'prefix=/usr\nexec_prefix=${prefix}\nlibdir=${prefix}/lib/x86_64-linux-gnu\nincludedir=${prefix}/include\nsysconfdir=/etc\nlocalstatedir=/var\nPACKAGE=fontconfig\nconfdir=${sysconfdir}/fonts\ncachedir=${localstatedir}/cache/${PACKAGE}\n\nName: Fontconfig\nDescription: Font configuration and customization library\nVersion: 2.15.0\nRequires:  freetype2 >= 21.0.15\nRequires.private:  expat\nLibs: -L${libdir} -lfontconfig\nLibs.private:  \nCflags: -I${includedir}  \n',
    'pixman-1': 'prefix=/usr\nexec_prefix=${prefix}\nlibdir=${prefix}/lib/x86_64-linux-gnu\nincludedir=${prefix}/include\n\nName: Pixman\nDescription: The pixman library (version 1)\nVersion: 0.42.2\nCflags: -I${includedir}/pixman-1\nLibs: -L${libdir} -lpixman-1\n\n',
    'openssl': 'prefix=/usr\nexec_prefix=${prefix}\nlibdir=${exec_prefix}/lib/x86_64-linux-gnu\nincludedir=${prefix}/include\n\nName: OpenSSL\nDescription: Secure Sockets Layer and cryptography libraries and tools\nVersion: 3.0.13\nRequires: libssl libcrypto\n',
    'libssl': 'prefix=/usr\nexec_prefix=${prefix}\nlibdir=${exec_prefix}/lib/x86_64-linux-gnu\nincludedir=${prefix}/include\n\nName: OpenSSL-libssl\nDescription: Secure Sockets Layer and cryptography libraries\nVersion: 3.0.13\nRequires.private: libcrypto\nLibs: -L${libdir} -lssl\nCflags: -I${includedir}\n',
    'libcrypto': 'prefix=/usr\nexec_prefix=${prefix}\nlibdir=${exec_prefix}/lib/x86_64-linux-gnu\nincludedir=${prefix}/include\nenginesdir=${libdir}/engines-3\nmodulesdir=${libdir}/ossl-modules\n\nName: OpenSSL-libcrypto\nDescription: OpenSSL cryptography library\nVersion: 3.0.13\nLibs: -L${libdir} -lcrypto\nLibs.private: -ldl -pthread \nCflags: -I${includedir}\n',
    'sqlite3': '# Package Information for pkg-config\n\nprefix=/usr\nexec_prefix=${prefix}\nlibdir=${prefix}/lib/x86_64-linux-gnu\nincludedir=${prefix}/include\n\nName: SQLite\nDescription: SQL database engine\nVersion: 3.45.1\nLibs: -L${libdir} -lsqlite3\nLibs.private: -lm -lz \nCflags: -I${includedir}\n',
    'libxml-2.0': 'prefix=/usr\nexec_prefix=${prefix}\nlibdir=${prefix}/lib/x86_64-linux-gnu\nincludedir=${prefix}/include\nmodules=1\n\nName: libXML\nVersion: 2.9.14\nDescription: libXML library version2.\nRequires:\nLibs: -L${libdir} -lxml2\nLibs.private: -licui18n -licuuc -licudata   -lz  -llzma   -lm  \nCflags: -I${includedir}/libxml2 \n',
    'liblzma': '#\n# Author: Lasse Collin\n#\n# This file has been put into the public domain.\n# You can do whatever you want with this file.\n#\n\nprefix=/usr\nexec_prefix=/usr\nlibdir=/usr/lib/x86_64-linux-gnu\nincludedir=/usr/include\n\nName: liblzma\nDescription: General purpose data compression library\nURL: https://tukaani.org/xz/\nVersion: 5.4.5\nCflags: -I${includedir}\nCflags.private: -DLZMA_API_STATIC\nLibs: -L${libdir} -llzma\nLibs.private: -pthread -lpthread\n',
}
